def aggressive_cows(stalls, cows):
    stalls.sort()

    def fits(gap):
        placed, last = 1, stalls[0]
        for position in stalls[1:]:
            if position - last >= gap:
                placed += 1
                last = position
        return placed >= cows

    low, high = 1, stalls[-1] - stalls[0]
    while low < high:
        mid = (low + high + 1) // 2
        if fits(mid):
            low = mid
        else:
            high = mid - 1
    return low

